<?php
require_once __DIR__.'/../../includes/accounting_ui.php';
$search=trim($_GET['q']??'');$status=$_GET['status']??'';$class=(int)($_GET['class_id']??0);$rows=$ac->rows('SELECT i.*,c.name class_name FROM ac_invoices i LEFT JOIN classes c ON c.id=i.class_id WHERE i.school_id=? AND (i.customer_name LIKE ? OR i.number LIKE ?)'.($class?' AND i.class_id=?':'').' ORDER BY i.id DESC',[$school,'%'.$search.'%','%'.$search.'%',...($class?[$class]:[])]);
if($status)$rows=array_values(array_filter($rows,fn($i)=>$ac->invoiceStatus($i)===$status));$page=max(1,(int)($_GET['page']??1));$count=count($rows);$rows=array_slice($rows,($page-1)*25,25);ob_start();
?>
<form class="row g-2 mb-3"><div class="col-md-5"><input type="search" name="q" class="form-control" value="<?= sanitize($search) ?>" placeholder="Invoice number or student/customer name" aria-label="Find invoice"></div><div class="col-md-4"><?php acSelect('status','Status',acChoices(['draft'=>'Draft','unpaid'=>'Unpaid','partially_paid'=>'Partially paid','paid'=>'Paid','overdue'=>'Overdue','void'=>'Cancelled / void']),$status,'id','name',false); ?></div><div class="col"><button class="btn btn-primary">Filter</button></div></form>
<div class="card card-body table-responsive"><table class="table ac-table"><thead><tr><th>Invoice</th><th>Date</th><th>Customer</th><th>Class</th><th>Total</th><th>Remaining</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><a href="<?= acUrl('invoice',['id'=>$r['id']]) ?>"><?= sanitize($r['number']?:'Draft #'.$r['id']) ?></a></td><td><?= sanitize(schoolDateLabel($r['bill_date'],'both','ymd')) ?></td><td><?= sanitize($r['customer_name']) ?></td><td><?= sanitize($r['class_name']??'—') ?></td><td><?= acMoney((int)$r['total_minor']) ?></td><td><?= acMoney($ac->invoiceBalance((int)$r['id'])) ?></td><td><?= sanitize(ucwords(str_replace('_',' ',$ac->invoiceStatus($r)))) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7">No matching invoices. Create a manual bill or generate assigned fees.</td></tr><?php endif; ?></tbody></table><p><?= $count ?> invoices · Page <?= $page ?> / <?= max(1,(int)ceil($count/25)) ?></p><div><?php if($page>1): ?><a class="btn btn-light" href="<?= acUrl('invoices',array_replace($_GET,['page'=>$page-1])) ?>">Previous</a><?php endif; ?><?php if($page*25<$count): ?><a class="btn btn-light" href="<?= acUrl('invoices',array_replace($_GET,['page'=>$page+1])) ?>">Next</a><?php endif; ?></div></div>
<?php acRender('Invoices',ob_get_clean());
